from __future__ import annotations

import logging
import json

import requests

from taf.hw.pdu.devices.http_client import HttpPdu
from taf.hw.pdu.devices.ssh_connection import SshConnection
from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.exceptions import BadDeviceStatus, BadPortNumber


class ZentronicsSSH(SshConnection):
    def __init__(self, host: str, login: str = "admin", password: str = "admin@1234", port: int = 22):
        super().__init__(host=host, login=login, password=password, port=port)
        self._sudo_password = password

    def power_on(self, port: int):
        return self._set_port_status(port, DeviceStatus.ON)

    def power_off(self, port: int):
        return self._set_port_status(port, DeviceStatus.OFF)

    def get_port_status(self, port: int):
        cmd = f"pdustat --json {port}"
        logging.debug(f"[Zentronics] Sending command: {cmd}")
        result = self.execute_command(cmd)
        logging.debug(f"[Zentronics] Received response: {result}")

        try:
            data = json.loads(result)
            status = data.get("status")
            return DeviceStatus.ON if status.upper() == "ON" else DeviceStatus.OFF
        except (json.JSONDecodeError, UnicodeDecodeError, TypeError):
            return result

    def _set_port_status(self, port: int, status: str):
        base_cmd = f"sudo -S -p '' pductl {self._port_setting[status]} {port}"
        cmd = f"printf '%s\\n' '{self._sudo_password}' | {base_cmd}"
        logging.debug(f"[Zentronics] Sending command: {base_cmd}")
        return self.execute_command(cmd)

    @property
    def _port_setting(self):
        return {DeviceStatus.OFF: "off", DeviceStatus.ON: "on"}


class ZSPSU48D(ZentronicsSSH):
    def __init__(self, host: str, login: str = "admin", password: str = "admin@1234", port: int = 22):
        super().__init__(host, login=login, password=password, port=port)


class ZentronicsHTTP(HttpPdu):
    def __init__(self, host: str, **kwargs):
        timeout = kwargs.get("timeout", 5)
        super().__init__(host, timeout=timeout)
        self._num_of_ports = 0  # must be set in child class
        self._url = f"http://{self._host}/pdu_api.php"

    def power_on(self, port: int) -> None:
        self._set_port_status(port, "ON")

    def power_off(self, port: int) -> None:
        self._set_port_status(port, "OFF")

    def get_port_status(self, port: int) -> str:
        response = self._get_port_status(port)
        parsed_response = self._parse_response(response, port)
        return self._reversed_port_settings[parsed_response]

    def reset(self, ports: list[int], time_interval: float | None = None):
        # for this device `time_interval` is not actually required
        # since full reset is done by sending a single request, but we need to keep the same interface for all devices
        for port in ports:
            self._validate_port(port)
            self._send_request(
                self._url,
                data={"outlet": port, "cmd": "RESET"},
            )

    def _validate_port(self, port: int):
        if not 1 <= port <= self._num_of_ports:
            raise BadPortNumber(f"Invalid port number: {port}")

    @property
    def _port_setting(self):
        return {DeviceStatus.ON: 1, DeviceStatus.OFF: 0}

    def _build_request_url(self, port: int, status: str):
        # from abstract base class, not used in this implementation
        pass

    def _parse_response(self, response: requests.Response, port: int) -> str | int:
        resp = self._preprocess_response(response)
        return resp["data"]["ports"][0]["state"]

    @staticmethod
    def _preprocess_response(response: requests.Response) -> dict:
        resp = response.json()
        resp_status = resp.get("status", "")
        if resp_status != "success":
            raise BadDeviceStatus(response.content.decode())
        return resp

    def _set_port_status(self, port: int, status: str):
        self._validate_port(port)
        logging.info(f"[Zentronics] Setting port to {status}: {port}")
        self._send_request(
            self._url,
            method="POST",
            data={"outlet": port, "cmd": status.upper()},
        )

    def _get_port_status(self, port: int) -> requests.Response:
        self._validate_port(port)
        logging.info(f"[Zentronics] Fetching status of port: {port}")
        return self._send_request(self._url, params={"outlet": port})


class ZS40DCB16iV(ZentronicsHTTP):
    def __init__(self, host: str, **kwargs):
        super().__init__(host, **kwargs)
        self._num_of_ports = 16

    def get_current(self, port: int) -> float:
        self._validate_port(port)
        response = self._get_port_status(port)
        return self._parse_response_for_current(response)

    def _parse_response_for_current(self, response: requests.Response) -> float:
        resp = self._preprocess_response(response)
        port_data = resp["data"]["ports"][0]
        return port_data["current_A"] if port_data["state"] == 1 else 0.0


class PDU8P30A8B(ZentronicsHTTP):
    def __init__(self, host: str, **kwargs):
        super().__init__(host, **kwargs)
        self._num_of_ports = 8

    @property
    def _port_setting(self):
        return {DeviceStatus.ON: "ON", DeviceStatus.OFF: "OFF"}

    @staticmethod
    def _preprocess_response(response: requests.Response) -> dict:
        resp = response.json()
        return resp

    def _parse_response(self, response: requests.Response, port: int) -> str:
        resp = self._preprocess_response(response)
        return resp["state"]
